import { confirmMemberEmail } from "@/lib/members/actions";
import { sanitizeMemberNextPath } from "@/lib/members/auth-results";

function nextPathFromSearchParams(value: string | undefined) {
  if (!value) return "/member";

  // The Supabase template may pass .RedirectTo, which is the callback URL
  // generated by the app. Recover only its allow-listed `next` value.
  try {
    const url = new URL(value);
    return sanitizeMemberNextPath(url.searchParams.get("next"));
  } catch {
    return sanitizeMemberNextPath(value);
  }
}

export default function ConfirmEmailPage({
  searchParams,
}: {
  searchParams: Record<string, string | undefined>;
}) {
  const tokenHash = searchParams.token_hash?.trim() ?? "";
  const type = searchParams.type;
  const next = nextPathFromSearchParams(searchParams.next);
  const validLink = type === "email" && tokenHash.length > 0 && tokenHash.length <= 512;

  return (
    <main className="min-h-screen bg-[#07111f] px-4 py-16 text-white sm:py-24">
      <section className="mx-auto w-full max-w-md rounded-[32px] border border-white/15 bg-[#0f1724] p-7 shadow-2xl shadow-black/50 sm:p-9">
        <p className="text-[11px] font-semibold uppercase tracking-[0.2em] text-[#7dd3fc]">SnowForce account</p>
        <h1 className="mt-3 text-3xl font-semibold tracking-[-0.5px]">Confirm your email</h1>
        {validLink ? (
          <>
            <p className="mt-3 text-sm leading-6 text-white/65">
              Press the button below to confirm your email address and finish creating your account.
            </p>
            <p className="mt-2 text-sm leading-6 text-white/50">
              请点击下方按钮确认邮箱，完成账户创建。
            </p>
            <form action={confirmMemberEmail} className="mt-7">
              <input type="hidden" name="tokenHash" value={tokenHash} />
              <input type="hidden" name="next" value={next} />
              <button className="auth-primary-button w-full">Confirm email address</button>
            </form>
          </>
        ) : (
          <>
            <p className="mt-3 text-sm leading-6 text-white/65">
              This confirmation link is invalid or has expired. Request a new verification email from the member sign-in page.
            </p>
            <a className="mt-7 inline-flex text-sm font-semibold text-[#7dd3fc] hover:text-white" href="/member">
              Go to member sign-in
            </a>
          </>
        )}
      </section>
    </main>
  );
}
